/**
 * Daily throttle ("cost airbag"). Counts how many tickets were created today
 * using n8n's persistent workflow static data. Resets automatically each day.
 * Limit = 10 per day. Runs BEFORE the Groq call so no AI cost is incurred once
 * the limit is reached.
 */
const LIMIT = 10;
const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);

if (staticData.counterDate !== today) {
  staticData.counterDate = today;
  staticData.counter = 0;
}

const used = staticData.counter || 0;
const limitReached = used >= LIMIT;

return [{
  json: {
    ...$input.item.json,
    throttle: { used, limit: LIMIT, limitReached },
  },
}];

/**
 * Assembles a Join-compatible task.
 * - title: from the AI (short, in the email's language)
 * - description: VERBATIM from the original email (never AI-rewritten/translated)
 * - category / priority / dueDate: classified by the AI
 * - creator: the sender, marked as external
 * Also repairs UTF-8/Latin-1 mojibake (Ã¤ -> ä) that some mail servers produce.
 */

/**
 * Fixes "mojibake" — UTF-8 bytes that were misread as Latin-1, turning
 * umlauts like ä into Ã¤. Re-decodes the string as UTF-8.
 * @param {string} text - Possibly broken text
 * @returns {string} Repaired text with correct German characters
 */
function fixEncoding(text) {
  if (!text) return '';
  // Only repair if the tell-tale "Ã" / "Â" sequences are present
  if (!/Ã|Â/.test(text)) return text;
  try {
    return Buffer.from(text, 'latin1').toString('utf8');
  } catch (e) {
    return text;
  }
}

// 1) Parse the AI answer (strip fences / think tags defensively)
const raw = $json.choices[0].message.content || '';
const cleaned = raw
  .replace(/```json|```/g, '')
  .replace(/<think>[\s\S]*?<\/think>/g, '')
  .trim();

let ai;
try {
  ai = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI did not return valid JSON: ' + raw);
}

// 2) Original email parts (from the Edit Fields node), encoding-repaired
const senderEmail = fixEncoding($('Edit Fields').item.json.senderEmail || '');
const senderName  = fixEncoding($('Edit Fields').item.json.senderName || '');
const emailText   = fixEncoding($('Edit Fields').item.json.emailText || '');

// 3) Description = original email body (verbatim), without the "Betreff:" line
const lines = emailText.split('\n');
const bodyText = lines.slice(1).join('\n').trim();
const description = (bodyText || emailText).trim() + '\n— Dieses Ticket wurde KI-generiert.';

// 4) Title from AI (also encoding-repaired), fallback to subject line
const subjectLine = (lines[0] || '').replace(/^Betreff:\s*/i, '').trim();
const title = fixEncoding((ai.title && String(ai.title).trim()) || subjectLine || 'Anfrage');

// 5) Validate the AI's classification values
const priority = ['Urgent', 'Medium', 'Low'].includes(ai.priority) ? ai.priority : 'Medium';
const category = ai.category === 'Technical Tasks' ? 'Technical Tasks' : 'User Story';
const dueDate  = typeof ai.dueDate === 'string' ? ai.dueDate : '';

// 6) Build the full task object
const task = {
  title,
  description,
  dueDate,
  priority,
  category,
  status: 'triage',
  assignedTo: [],
  subtasks: [],
  creator: { name: senderName, email: senderEmail, type: 'external' },
};

return [{ json: { task } }];

/**
 * Increments the daily counter after a ticket was successfully created.
 * Also writes the current count to Firebase so the Landing Page can
 * display it live without needing access to n8n directly.
 */
const LIMIT = 10;
const FIREBASE_URL = "https://join-60a91-default-rtdb.europe-west1.firebasedatabase.app";

const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);

if (staticData.counterDate !== today) {
  staticData.counterDate = today;
  staticData.counter = 0;
}
staticData.counter = (staticData.counter || 0) + 1;

const used = staticData.counter;
const remaining = Math.max(0, LIMIT - used);

await this.helpers.httpRequest({
  method: 'PUT',
  url: `${FIREBASE_URL}/dailyCounter.json`,
  body: {
    date: today,
    used,
    remaining,
    limit: LIMIT,
  },
  json: true,
});

return [{ json: { counter: used, remaining } }];

/**
 * Builds the request body for the Groq API as a clean object.
 * Doing this in a Code node (instead of typing JSON into the HTTP node)
 * avoids "not valid JSON" errors caused by line breaks, quotes or umlauts
 * in the email text — JSON.stringify is handled by n8n internally here.
 */

const emailText = $json.emailText || '';
const today = new Date().toISOString().slice(0, 10);

const systemPrompt =
  "You are a triage assistant for the Join Kanban board. You receive an email and return ONLY a strictly valid JSON object (no preamble, no explanation, no markdown fences) with exactly four fields: title, category, priority, dueDate. " +
  "RULES: title = a short clear ticket title, max ~60 chars, written in the EXACT SAME LANGUAGE as the email (a German email gets a German title, never translate). " +
  "category = exactly 'Technical Tasks' or 'User Story' ('User Story' for feature requests or user wishes, 'Technical Tasks' for bugs, errors, crashes or backend work). " +
  "priority = exactly 'Urgent', 'Medium' or 'Low'. Choose Urgent for high importance/urgency in any language, incl. German: dringend, sehr wichtig, wichtig, sofort, so schnell wie moeglich, kritisch, blockiert, Ausfall, Notfall, eilt; or English: urgent, asap, critical, blocker, broken, crash, production down, security, data loss. " +
  "Choose Low for: nice to have, waere schoen, kein Stress, irgendwann, kleinigkeit, kosmetisch, unwichtig, minor, no rush. Choose Medium only when there is no clear signal. " +
  "dueDate = 'YYYY-MM-DD' if a deadline is mentioned or implied (e.g. 'bis Ende Monat', 'bis am 15. Juli'), resolved against today " + today + ", otherwise empty string ''. " +
  "Do NOT write a description.";

const userPrompt =
  "Erstelle das JSON fuer diese E-Mail. Der Titel MUSS in der Sprache der E-Mail sein (deutsche Mail = deutscher Titel, niemals uebersetzen). " +
  "Achte bei der Prioritaet auf deutsche Dringlichkeits-Woerter wie 'wichtig' oder 'dringend'.\n\n--- EMAIL ---\n" +
  emailText +
  "\n--- END ---";

const requestBody = {
  model: 'llama-3.3-70b-versatile',
  temperature: 0.1,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt },
  ],
};

// Pass the body through (as a string) plus keep the original fields
return [{
  json: {
    ...$json,
    groqBody: JSON.stringify(requestBody),
  },
}];
